parameters.jsCode:
// Единственное место, где мы знаем, из какого мессенджера пришло сообщение.
// Ниже по течению весь граф работает с каналонезависимой формой.
// Причина: у Telegram идентификатор числовой, у WhatsApp — строка wa_id.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let n = null;

  // ── WhatsApp Cloud API ──
  const waMsg = j.messages?.[0] || j.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
  if (waMsg) {
    const contact = j.contacts?.[0] || j.entry?.[0]?.changes?.[0]?.value?.contacts?.[0];
    n = {
      channel: 'whatsapp',
      user_ref: String(waMsg.from),
      message_id: waMsg.id,
      text: waMsg.text?.body || waMsg.button?.text || waMsg.interactive?.button_reply?.title || '',
      payload: waMsg.interactive?.button_reply?.id || waMsg.button?.payload || null,
      profile_name: contact?.profile?.name || null,
      ts: waMsg.timestamp ? new Date(Number(waMsg.timestamp) * 1000).toISOString() : new Date().toISOString(),
    };
    // Вложение без текста: запоминаем тип, чтобы ответить по-человечески, а не молчать.
    if (!n.text) n.unsupported_kind = waMsg.type || 'unknown';
  }

  // ── Telegram ──
  if (!n && (j.message || j.callback_query)) {
    const cq = j.callback_query;
    const m = cq ? cq.message : j.message;
    n = {
      channel: 'telegram',
      user_ref: String((cq ? cq.from.id : m.chat.id)),
      message_id: String(m.message_id),
      text: cq ? (cq.data || '') : (m.text || ''),
      payload: cq ? cq.data : null,
      profile_name: [ (cq ? cq.from : m.from)?.first_name, (cq ? cq.from : m.from)?.last_name ]
                      .filter(Boolean).join(' ') || null,
      username: (cq ? cq.from : m.from)?.username || null,
      ts: new Date().toISOString(),
    };
    // Вложение без текста: определяем тип, чтобы ответить по-человечески, а не молчать.
    if (!cq && !n.text) {
      const KINDS = ['voice', 'audio', 'photo', 'video', 'video_note', 'document', 'sticker', 'location', 'contact'];
      n.unsupported_kind = KINDS.find((k) => m[k] !== undefined) || 'unknown';
      n.text = '';
    }
  }

  if (!n) continue;                         // совсем чужой апдейт — пропускаем молча

  // Молчание системы — дефект, а не «неподдерживаемый формат». Сообщение без текста
  // не выбрасываем: кладём готовый ответ и метку, по которой узел 1a уводит его
  // сразу в единую точку ответа (узел 12) — с дисклеймером и записью в журнал.
  if (!n.text) {
    n.status = 'unsupported_input';
    n.lang = 'ru';
    n.reply = (n.unsupported_kind === 'voice' || n.unsupported_kind === 'audio' || n.unsupported_kind === 'video_note')
      ? 'Я пока понимаю только текст — голосовые не расшифровываю. Напишите, пожалуйста, сообщением, и я сразу отвечу.'
      : 'Я понимаю только текстовые сообщения. Напишите, пожалуйста, текстом — например, «Хочу забронировать столик на двоих в субботу в 19:00».';
    n.trace_id = `${n.channel}-${n.user_ref}-${n.message_id}`;
    out.push({ json: n });
    continue;
  }

  // Профиль моделей: переключатель LOCAL / CLOUD.
  n.model_profile = 'LOCAL';
  // Признак того, что гость нажал кнопку согласия (проверяется в консент-гейте).
  n.is_consent_accept = (n.payload === 'consent_accept') ||
                        /^(принимаю|принять|accept|einverstanden)$/i.test(n.text.trim());
  n.trace_id = `${n.channel}-${n.user_ref}-${n.message_id}`;
  out.push({ json: n });
}
return out;

// Сознательное бездействие: сообщение принято и попадёт в журнал, но ответа не будет —
// с гостем в этот момент разговаривает человек.
const j = $('1. Нормализатор канала').item.json;
return [{ json: { ...j, intent: 'human_takeover', agent: 'оператор',
                  reply: null, status: 'escalated', text_masked: '[диалог у оператора]' } }];

// Уведомление собирается КОДОМ, а не моделью: комплаенс не должен зависеть от того,
// вспомнит ли языковая модель про дисклеймер (урок M14).
const CONSENT_VERSION = 'v1-2026-08';
const TEXT =
  'Здравствуйте! Это автоматический ассистент ресторана «Базилик» — вы общаетесь с программой, ' +
  'а не с сотрудником.\n\n' +
  'Чтобы принять бронь, мы обработаем ваше имя, номер телефона и детали визита. ' +
  'Данные хранятся на наших серверах, используются только для бронирования и связи с вами ' +
  'и не передаются третьим лицам, кроме мессенджера, через который вы пишете.\n' +
  'Вы можете в любой момент попросить удалить свои данные или позвать администратора.\n\n' +
  'Нажмите «Принимаю», чтобы продолжить, или позвоните нам: +49 30 442 17 88.';
const nrm = $('1. Нормализатор канала').item.json;
// Текст уходит и в consent_text (для аудита), и в reply: узел 12 собирает ответ гостю
// именно из reply. Без этого гость видел одну строку дисклеймера, не видел просьбы
// принять условия — и круг не размыкался: без согласия ни один агент не запускается.
// status — не 'answered': ответа по существу мы не дали, а W4 (Eval) считает качество только по 'answered'.
return [{ json: { ...nrm, consent_text: TEXT, consent_version: CONSENT_VERSION,
                  reply: TEXT, lang: nrm.lang || 'ru', status: 'consent_requested' } }];

// Маскируем ДО обращения к модели и ДО построения эмбеддинга запроса.
// Порядок важен: если сначала посчитать эмбеддинг, персональные данные уже утекли в вектор.
//
// 🔴 Урок 20.08 (прогон 1978), решение штаба ЗАДАНИЕ-28: токен-счётчик — дефект модели
// данных. [PHONE_1] уникален внутри сообщения, а pii_registry.token объявлен UNIQUE.
// Первый телефон занимал [PHONE_1] навсегда, номера следующих гостей молча отбрасывались
// (ON CONFLICT DO NOTHING), и администратор, разворачивая токен, получил бы ЧУЖОЙ номер.
// Теперь суффикс случайный: токен уникален по построению, а не по счётчику.
// 🔴 Прогон 2016 (первое голосовое): узел берёт данные у нормализатора ПО ИМЕНИ, а не
// у своего входа. На голосовой ветке у нормализатора text = '' и заготовленный ответ
// «понимаю только текст» — расшифровка в маску не попадала, роутер получал пустоту
// и отвечал гостю по-английски (intent other, lang en).
// Текстовая ветка не затронута: если узла 1v3 в прогоне не было, обращение к нему
// бросает исключение, и мы берём нормализатор — ровно как раньше.
let src;
try { src = $('1v3. Собрать элемент из расшифровки').item.json; }
catch (e) { src = $('1. Нормализатор канала').item.json; }
let text = src.text || '';
const map = [];

// Алфавит без похожих знаков (нет 0/O, 1/I): 32 символа, суффикс 6 знаков → 32^6 ≈ 1,07 млрд.
const ALPHABET = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
const SUFFIX_LEN = 6;

const seen = new Map();   // значение → токен: один и тот же номер в сообщении = один токен
const used = new Set();   // страховка от совпадения двух суффиксов внутри одного сообщения

const suffix = () => Array.from({ length: SUFFIX_LEN },
  () => ALPHABET[Math.floor(Math.random() * ALPHABET.length)]).join('');

// Ключ сравнения: у телефона только цифры (+49 176 55 и 0176-55 — это один номер),
// у остального регистр и края не считаются.
const keyOf = (type, value) => type + ':' + (type === 'phone'
  ? String(value).replace(/\D/g, '')
  : String(value).trim().toLowerCase());

function tokenFor(kind, type, value) {
  const key = keyOf(type, value);
  if (seen.has(key)) return seen.get(key);
  let t;
  do { t = '[' + kind + '_' + suffix() + ']'; } while (used.has(t));
  used.add(t); seen.set(key, t);
  map.push({ token: t, type, value: String(value).trim() });
  return t;
}

text = text.replace(/[\w.\-+]+@[\w\-]+\.[\w.\-]+/g, m => tokenFor('EMAIL', 'email', m));
text = text.replace(/(\+?\d[\d\s\-()]{7,}\d)/g, m => tokenFor('PHONE', 'phone', m));
text = text.replace(/@([A-Za-z0-9_]{4,})/g, m => tokenFor('TG', 'username', m));

// Имя из профиля мессенджера в текст не входит, но в контекст агента попасть может —
// маскируем и его. Имя, НАБРАННОЕ СЛОВАМИ в тексте гостя, маска не ловит: это известное
// ограничение, оно идёт строкой в «Ограничения системы» и в DPIA.
let guest_token = null;
if (src.profile_name) {
  guest_token = tokenFor('GUEST', 'name', src.profile_name);
  text = text.split(src.profile_name).join(guest_token);
}

// ВАЖНО: упоминания аллергии НЕ маскируются — это и есть предмет запроса (ст. 9 GDPR:
// обрабатываем минимально, в профиль гостя не сохраняем, в журнал пишем только
// замаскированный текст).
return [{ json: { ...src, text_masked: text, guest_token, pii_map: map,
                  pii_count: map.length } }];

