{
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "enum": [
        "new_booking",
        "change_booking",
        "cancel_booking",
        "banquet_request",
        "menu_question",
        "allergen_question",
        "recommendation",
        "policy_question",
        "complaint",
        "other"
      ]
    },
    "confidence": {
      "type": "string",
      "enum": [
        "high",
        "mid",
        "low"
      ]
    },
    "lang": {
      "type": "string",
      "description": "ISO 639-1, два символа в нижнем регистре"
    },
    "query_norm": {
      "type": "string",
      "description": "Поисковая строка для базы знаний: название блюда точно как в меню и в именительном падеже + тема (аллергены, состав, цена, правило). Всегда по-русски, регистр названий сохранять"
    },
    "slots": {
      "type": "object",
      "properties": {
        "party_size": {
          "type": "number"
        },
        "date": {
          "type": "string"
        },
        "time": {
          "type": "string"
        },
        "dish": {
          "type": "string"
        },
        "allergen": {
          "type": "string"
        },
        "booking_ref": {
          "type": "string"
        },
        "children": {
          "type": "number"
        }
      }
    }
  },
  "required": [
    "intent",
    "confidence",
    "lang",
    "query_norm"
  ]
}

parameters.jsCode:
// Страховка на случай, если модель вернула мусор или неизвестный интент.
// Ключевые слова — не «умнее» модели, они лишь не дают запросу провалиться в никуда.
const ALLOWED = ['new_booking','change_booking','cancel_booking','banquet_request',
  'menu_question','allergen_question','recommendation','policy_question','complaint','other'];

// Слова, по которым вопрос считается вопросом об аллергенах.
// Правка 19.08 по итогам ревью: раньше здесь искалось только слово «аллергия»,
// поэтому вопрос «в Капрезе есть соя?» уходил в обычный вопрос по меню — а это вопрос
// о здоровье, заданный без слова «аллергия». Так спрашивает половина людей.
// Список — 14 аллергенов из приложения II Регламента (ЕС) 1169/2011, на трёх языках,
// плюс формы вроде «без глютена». Ошибка в сторону аллергенов безопасна: оба интента
// обслуживает один и тот же агент А2, меняется только строгость правил в промпте.
const ALLERGEN_RE = new RegExp([
  'аллерг','непереносим','allerg','intolera','unvertr',
  'глютен','gluten','клейковин','целиак','zöliakie','zoliakie',
  'лактоз','laktose','lactose','молок','milch','milk','сливк','сыр\\b','käse',
  'яйц','\\bei(er|s)?\\b','\\begg','майонез',
  'орех','nuss','nüsse','nut\\b','арахис','erdnuss','peanut','миндал','mandel',
  'фундук','кешью','фисташк','пекан','макадам',
  'соя','сое','соев','soja','\\bsoy','тофу',
  'рыб','fisch','\\bfish','морепродукт','меeresfrüchte','креветк','краб','мидии',
  'ракообраз','моллюск','анчоус','krebstier','weichtier',
  'кунжут','sesam','sesame','горчиц','senf','mustard',
  'сельдере','sellerie','celery','люпин','lupine',
  'сульфит','диоксид серы','sulfit','sulphite','консервант'
].join('|'), 'i');
const pii = $('4. PII-маска (до любого LLM)').item.json;
// Два источника интента, и код понимает оба:
//  — chain + структурный парсер (gemma, узел 5) — отдаёт JSON в output;
//  — дообученный роутер (узел 5f) — ответ LM Studio с ОДНИМ СЛОВОМ в choices[0].
// Так переключение между моделями — это переключение связи, а не переписывание кода.
const raw0 = $input.first().json;
let r;
if (raw0 && raw0.choices) {
  const word = String(raw0.choices[0]?.message?.content || '').toLowerCase();
  const found = ALLOWED.find((i) => word.includes(i)) || '';
  // Дообученная модель не сообщает уверенность. Слово из списка — high;
  // всё остальное — low, а низкая уверенность ниже по коду ведёт к человеку.
  r = { intent: found, confidence: found ? 'high' : 'low', lang: null, query_norm: null, slots: {} };
} else {
  r = raw0.output || raw0;
}
let intent = String(r.intent || '').trim();
let confidence = ['high','mid','low'].includes(r.confidence) ? r.confidence : 'low';
const t = (pii.text_masked || '').toLowerCase();

if (!ALLOWED.includes(intent)) {
  if (ALLERGEN_RE.test(t)) intent = 'allergen_question';
  else if (/отменит|отмена|cancel|storn/.test(t))                       intent = 'cancel_booking';
  else if (/заброн|столик|стол на|reserv|tisch/.test(t))                intent = 'new_booking';
  else if (/жалоб|отврат|ужасн|безобраз|beschwerde/.test(t))            intent = 'complaint';
  else                                                                   intent = 'other';
  confidence = 'low';
}
// Правило безопасности дублируем кодом: цена пропуска аллергии слишком высока,
// чтобы полагаться только на модель.
if (ALLERGEN_RE.test(t) && !['allergen_question','complaint'].includes(intent)) {
  intent = 'allergen_question'; confidence = 'mid';
}
// Низкая уверенность = человек, без исключений.
const route = (confidence === 'low' || ['complaint','banquet_request','other'].includes(intent))
              ? 'escalate' : intent;

// 🔴 Язык определяем КОДОМ, а не спрашиваем у модели (прогон 2018): на русское
// «Нас будет 10 человек в пятницу» роутер вернул lang: 'de', и гость получил ответ
// по-немецки. Алфавит — детерминированный признак, угадывать его моделью незачем.
// На точность роутера не влияет: она считается по интентам, а интент здесь не меняется.
// Префикс [voice] латиницей на определение не влияет: кириллица в остатке строки сильнее.
const DE_RE = /[äöüß]|\b(ich|und|der|die|das|wir|möchte|moechte|tisch|uhr|bitte|für|fuer|haben|können|koennen|reservier\w*)\b/i;
const tl = String(pii.text_masked || '');
const lang = /[а-яёіїєґ]/i.test(tl) ? 'ru'
           : DE_RE.test(tl) ? 'de'
           : ['ru', 'de', 'en'].includes(r.lang) ? r.lang : 'ru';

return [{ json: { ...pii, intent, confidence, lang,
                  query_norm: r.query_norm || pii.text_masked, slots: r.slots || {},
                  route, started_at: Date.now() } }];

