parameters.jsCode:
// Часть правил проверяем кодом, а не доверяем модели: арифметика и сроки — не её сильная
// сторона, а ошибка здесь стоит гостю столика.
const ctx = $('5b. Нормализация intent + страховка').item.json;
const a = $input.first().json.output || $input.first().json;
const cfg = $('7a. Postgres — правила и занятость').item.json.config || {};
const b = a.booking || {};
const issues = [];

// ── НОРМАЛИЗАЦИЯ ДАТЫ И ВРЕМЕНИ. Добавлено 21.08 по ЗАДАНИЮ-43. ─────────────
// Агент возвращал booking_date человеческим текстом — «на ближайшую субботу».
// new Date("на ближайшую субботуT19:00") = Invalid Date, все сравнения с ней ложны,
// и ОБЕ проверки ниже — «меньше двух часов до визита» и «позже последней посадки» —
// молча не срабатывали, а узел 7d падал на приведении $6::date.
// Дату НЕ УГАДЫВАЕМ: не разобрали — null и вопрос гостю.
const MONTHS = { 'январ': 1, 'феврал': 2, 'март': 3, 'апрел': 4, 'ма': 5, 'июн': 6, 'июл': 7,
  'август': 8, 'сентябр': 9, 'октябр': 10, 'ноябр': 11, 'декабр': 12,
  'januar': 1, 'februar': 2, 'marz': 3, 'april': 4, 'mai': 5, 'juni': 6, 'juli': 7,
  'august': 8, 'september': 9, 'oktober': 10, 'november': 11, 'dezember': 12 };
const WDAYS = [['воскресен', 'sonntag', 'sunday'], ['понедельник', 'montag', 'monday'],
  ['вторник', 'dienstag', 'tuesday'], ['сред', 'mittwoch', 'wednesday'],
  ['четверг', 'donnerstag', 'thursday'], ['пятниц', 'freitag', 'friday'],
  ['суббот', 'samstag', 'sonnabend', 'saturday']];
// Сегодня именно в поясе ресторана, а не в UTC сервера: в 23:30 по Берлину это разные дни.
const todayISO = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const addDays = (iso, n) => { const t = new Date(iso + 'T12:00:00Z'); t.setUTCDate(t.getUTCDate() + n);
  return t.toISOString().slice(0, 10); };
const dowOf = iso => new Date(iso + 'T12:00:00Z').getUTCDay();

function normDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim().toLowerCase().replace(/ё/g, 'е');
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  let m = s.match(/(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{4}))?/);
  if (m) { const y = m[3] || todayISO.slice(0, 4);
    return y + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0'); }
  if (/сегодня|heute|today/.test(s)) return todayISO;
  if (/послезавтра|ubermorgen|übermorgen/.test(s)) return addDays(todayISO, 2);
  if (/завтра|morgen|tomorrow/.test(s)) return addDays(todayISO, 1);
  m = s.match(/(\d{1,2})\s*\.?\s*([а-я]+|[a-z]+)/);
  if (m) {
    // Сортировка по длине обязательна: иначе «марта» начинается на «ма» и становится маем.
    const key = Object.keys(MONTHS).sort((x, y2) => y2.length - x.length).find(k => m[2].startsWith(k));
    if (key) { const y = Number(todayISO.slice(0, 4));
      const iso = y + '-' + String(MONTHS[key]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
      return iso >= todayISO ? iso : (y + 1) + iso.slice(4); }
  }
  for (let i = 0; i < 7; i++) {
    if (WDAYS[i].some(w => s.includes(w))) {
      let delta = (i - dowOf(todayISO) + 7) % 7;
      if (delta === 0) delta = 7;   // «в субботу», сказанное в субботу, — это следующая суббота
      return addDays(todayISO, delta);
    }
  }
  return null;
}
function normTime(raw) {
  if (!raw) return null;
  const m = String(raw).trim().toLowerCase().match(/(\d{1,2})\s*[:.\s]?\s*(\d{2})?/);
  if (!m) return null;
  const h = Number(m[1]), mi = Number(m[2] || 0);
  if (!(h >= 0 && h <= 23 && mi >= 0 && mi <= 59)) return null;
  return String(h).padStart(2, '0') + ':' + String(mi).padStart(2, '0');
}

const rawDate = b.booking_date, rawTime = b.booking_time;
b.booking_date = normDate(rawDate);
b.booking_time = normTime(rawTime);
const date_unparsed = !!rawDate && !b.booking_date;
if (date_unparsed) issues.push('дата не распознана: «' + rawDate + '»');
// ─────────────────────────────────────────────────────────────────

const size = Number(b.party_size || ctx.slots?.party_size || 0);
const banquetFrom = Number(cfg.banquet_party_size || 15);
const prepayFrom  = Number(cfg.prepay_party_size || 8);
const perPerson   = Number(cfg.prepay_per_person || 15);

let action = a.action;
if (size >= banquetFrom) { action = 'escalate'; issues.push(`группа ${size} — банкет, нужен администратор`); }
const prepay = size >= prepayFrom && size < banquetFrom;
const prepaySum = prepay ? size * perPerson : 0;

// Минимальный срок брони
if (b.booking_date && b.booking_time) {
  // Часовой пояс. new Date('2026-08-21T03:30') без суффикса трактуется как время СЕРВЕРА (UTC),
  // а гость говорит по Берлину. Летом разница два часа — ровно порог min_lead_hours,
  // поэтому правило молчало: прогон 2102, бронь за 40 минут до визита дала leadH = 2,7.
  // Смещение считаем для КОНКРЕТНОЙ даты: зимой оно другое.
  const naive = new Date(b.booking_date + 'T' + b.booking_time + ':00Z');
  const offsetMs = new Date(naive.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }))
                 - new Date(naive.toLocaleString('en-US', { timeZone: 'UTC' }));
  const when = new Date(naive.getTime() - offsetMs);
  const leadH = (when - new Date()) / 36e5;
  if (isFinite(leadH) && leadH < Number(cfg.min_lead_hours || 2)) {
    action = 'escalate'; issues.push('меньше 2 часов до визита — по политике нужен администратор');
  }
  const last = String(cfg.last_seating || '21:30');
  if (b.booking_time > last) { action = 'escalate'; issues.push(`посадка позже ${last}`); }
  // Зеркальная проверка снизу. Без неё «завтра в 03:30» проходило бы: до визита больше
  // двух часов, а '03:30' < '21:30' при сравнении строк. Ресторан ночью закрыт.
  const first = String(cfg.first_seating || cfg.opening_time || '12:00');
  if (b.booking_time < first) { action = 'escalate'; issues.push(`посадка раньше ${first}`); }
}
// Ёмкость зала
const tables = Number(cfg.tables_count || 12);
if (Number($('7a. Postgres — правила и занятость').item.json.booked_that_day || 0) >= tables) {
  action = 'escalate'; issues.push('на эту дату свободных столов по журналу нет');
}

// Дату не разобрали — не угадываем и не пишем в базу, а честно спрашиваем.
let replyOut = a.reply;

// Агент осторожничает: увидев относительную дату («в субботу»), он ставит ask_more
// и переспрашивает «на какую именно субботу?» — даже когда есть и размер, и время, и имя.
// Дату теперь разбирает код, и если после нормализации есть ВСЁ необходимое и ни одно
// правило не нарушено — переспрашивать нечего. Решение принимает код, не модель:
// тот же принцип, что у страховки по аллергенам и у входного стоп-фильтра.
const haveAll = size > 0 && !!b.booking_date && !!b.booking_time;
let promoted = false;
if (action === 'ask_more' && haveAll && issues.length === 0) { action = 'create_booking'; promoted = true; }
if (date_unparsed || (action === 'create_booking' && (!b.booking_date || !b.booking_time))) {
  action = 'ask_more';
  const Q = { ru: 'Подскажите, пожалуйста, точную дату и время визита — например, «23 августа в 19:00».',
              de: 'Nennen Sie mir bitte das genaue Datum und die Uhrzeit — zum Beispiel «23. August um 19:00».',
              en: 'Could you tell me the exact date and time — for example “August 23 at 7 pm”?' };
  replyOut = Q[ctx.lang] || Q.ru;
}

const pad = n => String(n).padStart(2, '0');
// Номер брони рождается ТОЛЬКО когда бронь действительно создаётся (решение штаба, ЗАДАНИЕ-28).
// Раньше при ask_more гость мог увидеть BAS-00000000-36: номер несуществующей брони
// с обнулённой датой. Дата и время обязательны: без них строка всё равно не встанет в bookings.
const d = b.booking_date ? b.booking_date.replace(/-/g, '') : '00000000';
const can_book = action === 'create_booking' && !!b.booking_date && !!b.booking_time;
const booking_ref = can_book ? `BAS-${d}-${pad(Math.floor(Math.random() * 90) + 10)}` : null;

// Если бронь договорил код, то и подтверждение пишет код: ответ агента был вопросом.
// Номер брони гость видит ОТКРЫТЫМ — это не персональные данные, а его ключ к брони.
if (promoted && booking_ref) {
  const C = {
    ru: 'Готово! Бронь ' + booking_ref + ' подтверждена: ' + b.booking_date + ', ' + b.booking_time + ', гостей ' + size + '.',
    de: 'Fertig! Reservierung ' + booking_ref + ' bestätigt: ' + b.booking_date + ', ' + b.booking_time + ', ' + size + ' Personen.',
    en: 'Done! Booking ' + booking_ref + ' confirmed: ' + b.booking_date + ', ' + b.booking_time + ', ' + size + ' guests.' };
  replyOut = (C[ctx.lang] || C.ru) + (prepay ? ' Требуется предоплата ' + prepaySum + ' €.' : '');
}

return [{ json: { ...ctx, agent: 'А1', reply: replyOut, action,
  booking: { ...b, party_size: size }, booking_ref,
  prepay_required: prepay, prepay_note: prepay ? `предоплата ${prepaySum} € (${size} × ${perPerson} €)` : null,
  rule_issues: issues, escalation_reason: a.escalation_reason || issues.join('; ') || null } }];

// Postgres-нода затирает контекст своим результатом — возвращаем его на место
// и прикладываем карточки блюд как эталон для агента и для валидатора.
// Стоп-лист (available=false) читается живьём: он меняется в течение вечера
// и поэтому намеренно не хранится в векторном индексе.
const ctx = $('8b. Порог релевантности + стоп-лист').item.json;
const row = $input.first().json || {};
const cards = row.cards || [];
const stopList = row.stop_list || [];
return [{ json: { ...ctx,
  menu_cards: cards,
  menu_cards_count: cards.length,
  stop_list: stopList,
  stop_list_count: stopList.length } }];

// Порог откалиброван 19.08 на 12 контрольных запросах к залитой базе (замер):
// самое слабое ВЕРНОЕ попадание — 0.5057 (парковка), самое сильное ЧУЖОЕ — 0.4504.
// TH = 0.50 проходит все верные и отсекает оба мусорных запроса.
// Окно между ними всего 0.0189 — это не запас прочности, а результат на 12 примерах.
// Поэтому настоящая защита по аллергенам — эталонные карточки из Postgres (узел 8b2),
// а не порог: даже при grounded=false агент отвечает по карточке, а не по памяти.
const TH = 0.50;
// GAP считается и пишется в журнал как диагностика, но НЕ является гейтом:
// на этой базе окно между верными (мин. разрыв 0.0319) и чужими (макс. 0.0292)
// составляет 0.0027 — различить по нему нельзя, а ложные отказы он давал бы.
const GAP = null;
const ctx = $('5b. Нормализация intent + страховка').item.json;

const docs = $input.all()
  .map(i => i.json)
  .filter(d => d && (d.pageContent || d.document?.pageContent));

const norm = docs.map(d => ({
  text: d.pageContent || d.document?.pageContent || '',
  meta: d.metadata || d.document?.metadata || {},
  score: Number(d.score ?? d.document?.score ?? 0),
})).sort((a, b) => b.score - a.score);

const top = norm[0]?.score ?? 0;
const gap = top - (norm[1]?.score ?? 0);
const grounded = norm.length > 0 && top >= TH;

return [{ json: { ...ctx,
  kb_hits: norm.slice(0, 4),
  kb_context: norm.slice(0, 4).map((d, i) => `[${i + 1}] ${d.text}`).join('\n\n'),
  retrieval_top_score: Number(top.toFixed(4)),
  retrieval_gap: Number(gap.toFixed(4)),
  grounded,
  // Стоп-лист: наличие блюда в базе знаний не означает наличие его на кухне сегодня.
  // Находка из интервью с шеф-поваром: позиции заканчиваются в течение вечера.
  stoplist_disclaimer: true } }];

