parameters.jsCode:
// Откалибровано 19.08 на 12 контрольных запросах (см. комментарий в узле 8b).
// Для А3 порог важнее, чем для А2: здесь база знаний — единственный источник,
// эталонных карточек нет. Ниже порога агент обязан сказать «уточню у администратора».
const TH = 0.50;
const GAP = null; // диагностика, не гейт
const ctx = $('5b. Нормализация intent + страховка').item.json;
const norm = $input.all().map(i => i.json)
  .filter(d => d && (d.pageContent || d.document?.pageContent))
  .map(d => ({ text: d.pageContent || d.document?.pageContent || '',
               meta: d.metadata || d.document?.metadata || {},
               score: Number(d.score ?? d.document?.score ?? 0) }))
  .sort((a, b) => b.score - a.score);
const top = norm[0]?.score ?? 0;
return [{ json: { ...ctx, kb_hits: norm.slice(0, 4),
  kb_context: norm.slice(0, 4).map((d, i) => `[${i + 1}] ${d.text}`).join('\n\n'),
  retrieval_top_score: Number(top.toFixed(4)),
  retrieval_gap: Number((top - (norm[1]?.score ?? 0)).toFixed(4)),
  grounded: norm.length > 0 && top >= TH } }];

