parameters.jsCode:
// Единая форма для валидатора, независимо от того, какой агент отвечал.
const pick = (name) => { try { return $(name).item.json; } catch (e) { return null; } };
let raw = $input.first().json;
// Ветка А1: между агентом и этим узлом стоит 7d (запись брони). Он подменяет
// элемент своим ответом, а при неподтверждённой брони не возвращает ни строки —
// и сюда доезжала пустышка: reply = '', action = null. Судья честно писал
// «Отсутствует черновик ответа» и браковал ЛЮБУЮ бронь (найдено 20.08, прогон 1977).
if (!raw.reply && !raw.output) raw = pick('7c. Правила брони (проверка кодом)') || raw;
const a = raw.output || raw;
const ctx = $('5b. Нормализация intent + страховка').item.json;
// Контекст поиска лежит в узле порога: 8b (меню и аллергены) или 9b (консьерж).
// Ветка А1 (бронирование) не выполняет ни один из них, а обращение к невыполненному
// узлу в n8n бросает ошибку — поэтому по очереди и через try/catch.
// Без ветки 9b судья получал пустой контекст и браковал ЛЮБОЙ ответ консьержа
// как выдуманный — и вопрос уезжал человеку (найдено 20.08, прогон 1974).
const src = (raw.kb_hits ? raw : null)
         || pick('8b. Порог релевантности + стоп-лист')
         || pick('9b. Порог релевантности (консьерж)')
         // Ветка А1 базой знаний не пользуется: её источник правды — конфигурация
         // ресторана из узла 7a. Без неё судья бракует любую бронь со словами
         // «в контексте нет правил бронирования».
         || (() => { const cfg = pick('7a. Postgres — правила и занятость');
                     return cfg ? { kb_hits: [{ meta: { section: 'Правила ресторана (restaurant_config)' },
                                                score: null, text: JSON.stringify(cfg.config || {}) }] } : null; })()
         || {};
// Если бронь ДЕЙСТВИТЕЛЬНО записана в базу — судья обязан это видеть.
// Прогон 2106: строка BAS-20260822-82 легла в bookings, а судья забраковал ответ
// со словами «номер брони не подтверждается контекстом» — и гость получил
// «уточняю у администратора» при существующей брони. Это хуже отказа: гость думает,
// что стола нет, а стол занят. Судья судил верно — ему просто не дали факт.
const dbRow = (() => { try { const r = $('7d. Postgres — записать бронь').item.json;
  return (r && r.booking_ref) ? r : null; } catch (e) { return null; } })();
return [{ json: {
  ...ctx,
  agent: raw.agent || (ctx.intent === 'new_booking' ? 'А1' :
        (['menu_question','allergen_question'].includes(ctx.intent) ? 'А2' : 'А3')),
  reply: a.reply || raw.reply || '',
  needs_human: Boolean(a.needs_human || raw.action === 'escalate'),
  escalation_reason: a.escalation_reason || raw.escalation_reason || null,
  action: raw.action || null,
  booking_ref: raw.booking_ref || null,
  prepay_note: raw.prepay_note || null,
  grounded: a.grounded ?? src.grounded ?? raw.grounded ?? null,
  // Карточки блюд нужны валидатору как эталон, но ветка А2 выполняется не всегда:
  // обращение к неисполненной ноде бросает ошибку, поэтому берём осторожно.
  menu_cards: (() => { try { return $('8b3. Слить эталон с контекстом').item.json.menu_cards || null; }
                       catch (e) { return null; } })(),
  // Стоп-лист нужен валидатору: он проверяет, не предложил ли агент то, чего сегодня нет.
  stop_list: (() => { try { return $('8b3. Слить эталон с контекстом').item.json.stop_list || []; }
                      catch (e) { return []; } })(),
  stop_list_count: (() => { try { return $('8b3. Слить эталон с контекстом').item.json.stop_list_count || 0; }
                            catch (e) { return 0; } })(),
  retrieval_top_score: src.retrieval_top_score ?? null,
  retrieval_gap: src.retrieval_gap ?? null,
  // Судье нужен ТЕКСТ найденного, а не только название раздела и балл: он проверяет
  // фактичность ответа против контекста. По паре {section, score} проверить нечего,
  // и любой ответ выглядит выдуманным. Это же кормит RAG-метрики в журнале.
  kb_hits: [
    ...(dbRow ? [{ section: 'Подтверждение из базы (таблица bookings)', score: null,
        text: 'Бронь ' + dbRow.booking_ref + ' УЖЕ ЗАПИСАНА в базу данных ресторана: статус '
          + dbRow.status + ', дата ' + dbRow.booking_date + ', время ' + dbRow.booking_time
          + ', гостей ' + dbRow.party_size + '. Это факт из базы, а не утверждение модели. '
          + 'Подтверждение брони с этим номером — достоверно и в границах полномочий ассистента.' }] : []),
    ...(src.kb_hits || []).map(h => ({ section: h.meta?.section || h.meta?.dish,
                                       score: h.score, text: h.text })),
  ],
  // Счётчик попыток живёт во входных данных: на повторе он приходит из 10g.
  retry_count: Number(raw.retry_count ?? ctx.retry_count ?? 0),
} }];

