parameters.jsCode:
// Схема из брифа: невалидно первый раз → повтор с указанием проблем;
// невалидно второй раз → человек, а гостю честное «уточняю, отвечу в течение 15 минут».
// После повторной попытки контекст собирает 10g, на первом проходе — узел 10.
// Узел, который не выполнялся, бросает ошибку — отсюда try/catch.
let ctx = null;
try { ctx = $('10g. Сборка после повтора').item.json; } catch (e) { ctx = null; }
if (!ctx) ctx = $('10. Сборка ответа агента').item.json;
const v = ($input.first().json.output || $input.first().json);
const valid = Boolean(v.valid);
const issues = v.issues || [];
const retry = Number(ctx.retry_count || 0);

let decision;
if (valid && !ctx.needs_human) decision = 'send';
else if (!valid && retry < 1)  decision = 'retry';
else                            decision = 'escalate';

return [{ json: { ...ctx, validator_result: { valid, issues, severity: v.severity || 'none' },
                  decision, retry_count: retry + (decision === 'retry' ? 1 : 0),
                  escalation_reason: ctx.escalation_reason ||
                    (decision === 'escalate' ? (issues.join('; ') || 'ответ не прошёл проверку дважды') : null) } }];

