  "required": [
    "reply",
    "grounded",
    "needs_human"
  ]
}

parameters.jsCode:
// Приводим результат повторной попытки к той же форме, что и узел 10,
// чтобы валидатор проверял её теми же правилами. Счётчик попыток переносим:
// без него цикл «невалидно → повтор» никогда бы не закончился.
const prep = $('10e. Подготовка повтора').item.json;
const raw = $input.first().json;
const a = raw.output || raw;

return [{ json: { ...prep,
  reply: a.reply || '',
  needs_human: Boolean(a.needs_human),
  escalation_reason: a.escalation_reason || prep.escalation_reason || null,
  grounded: a.grounded ?? prep.grounded ?? null,
  menu_cards: prep.retry_menu_cards || null,
  stop_list: prep.retry_stop_list || [],
  stop_list_count: (prep.retry_stop_list || []).length,
  fixed_issues: a.fixed_issues || [],
  retry_count: Number(prep.retry_count || 1),
  was_retried: true } }];

// Postgres-нода затирает контекст своим результатом — возвращаем контекст на место.
// Попадание в кэш означает: на точно такой же нормализованный запрос уже был ответ,
// который прошёл валидатора, и с тех пор база знаний не менялась (сверка по отпечатку
// делается прямо в SQL). Тогда сочинять заново нечего.
const ctx = $('5b. Нормализация intent + страховка').item.json;
const row = $input.first().json || {};
const answer = row.answer || null;

if (!answer) {
  return [{ json: { ...ctx, cache_hit: false } }];
}
return [{ json: { ...ctx,
  cache_hit: true,
  reply: answer,
  agent: 'кэш',
  needs_human: false,
  status: 'answered',
  retry_count: 0,
  grounded: true,
  validator_result: { valid: true, issues: [], source: 'cache' } } }];

// Гость нажал кнопку в напоминании. Ни роутер, ни агенты, ни валидатор здесь не нужны:
// намерение известно точно, оно закодировано в самой кнопке. Такой ответ стоит ноль токенов.
const ctx = $('1. Нормализатор канала').item.json;
const row = $input.first().json || {};
const action = String(ctx.payload || '').split(':')[0];

let reply;
if (!row.booking_ref) {
  // Бронь не нашлась под этим гостем — либо уже отменена, либо кнопка из чужого чата.
  reply = 'Не получилось найти эту бронь. Напишите, пожалуйста, администратору — он проверит.';
} else if (row.status === 'visit_confirmed') {
  const t = String(row.booking_time || '').slice(0, 5);
  reply = `Спасибо, ждём вас! Бронь ${row.booking_ref} подтверждена: ${t}, ${row.party_size} чел.\n` +
          'Стол держим 15 минут от заявленного времени.';
} else {
  reply = `Бронь ${row.booking_ref} отменена. Спасибо, что предупредили — будем рады видеть вас в другой раз.`;
}

return [{ json: { ...ctx,
  intent: action === 'booking_confirm' ? 'booking_confirm' : 'booking_cancel',
  agent: 'кнопка',
  reply,
  lang: ctx.lang || 'ru',
  pii_map: [],
  consent_seen_before: true,   // кнопка приходит от гостя, который уже общался с ботом
  status: 'answered',
  cache_hit: false,
  needs_human: false,
  retry_count: 0,
  booking_ref: row.booking_ref || null,
  started_at: Date.now() } }];

// Узлы Telegram и WhatsApp возвращают ответ мессенджера ({ok, result}) и подменяют им
// содержимое элемента. До этого узла журнал видел именно их и писал пустые строки
// (user_ref_hash был md5 от пустой строки). Возвращаем на рельсы то, что собрал узел 12.
// Ветка «2c → 14» идёт мимо этого узла и не затронута — поэтому отдельный узел,
// а не ссылка на узел 12 прямо в параметрах узлов 14 и 15.
return [{ json: $('12. Единая точка ответа').item.json }];

// Гость только что принял условия. Слово «Принимаю» — не вопрос, вести его через
// роутер и агентов незачем: модель вынуждена была бы классифицировать его как other
// и гость получил бы бессмысленный ответ или эскалацию. Главное же — человек должен
// понять, что согласие принято, иначе он сидит и ждёт непонятно чего.
const j = $('1. Нормализатор канала').item.json;
return [{ json: { ...j,
  lang: j.lang || 'ru',
  intent: 'consent_accepted',
  agent: 'система',
  reply: 'Спасибо, согласие принято — теперь я могу помочь.\n\nСпросите про меню и аллергены, часы работы или условия — или забронируйте столик: «Столик на двоих в субботу в 19:00».',
  status: 'answered',
  needs_human: false,
  retry_count: 0,
  cache_hit: false } }];

// Ветка голоса. Контекст берём у нормализатора по имени, а НЕ у входа: выше два узла
// (Telegram и HTTP), каждый подменяет элемент своим ответом — главный урок 20.08.
const src = $('1. Нормализатор канала').item.json;
const stt = $input.first().json || {};
const text = String(stt.text || '').trim();

// Тот же список аллергенов, что в узле 5b: 14 позиций приложения II Регламента (ЕС) 1169/2011.
const ALLERGEN_RE = /аллерг|непереносим|allerg|intolera|unvertr|глютен|gluten|клейковин|целиак|лактоз|laktose|lactose|молок|milch|milk|сливк|сыр\b|käse|яйц|\begg|орех|nuss|nüsse|nut\b|арахис|erdnuss|peanut|миндал|mandel|фундук|кешью|фисташк|соя|соев|soja|\bsoy|тофу|рыб|fisch|\bfish|морепродукт|креветк|краб|мидии|моллюск|анчоус|кунжут|sesam|горчиц|senf|mustard|сельдере|sellerie|celery|люпин|lupine|сульфит|sulfit/i;

// Канал ОСТАЁТСЯ 'telegram'. Проверено фактом: chat_sessions и bookings имеют
// CHECK (channel IN ('whatsapp','telegram')), а сессия ищется по (channel, user_ref).
// Значение 'telegram_voice' создало бы вторую сессию (повторный запрос согласия GDPR)
// и уронило бы вставку брони. Признак голоса несём в поле source.
const base = { ...src, source: 'voice', voice_stt_ms: stt.stt_ms ?? null,
               voice_total_ms: stt.total_ms ?? null };
delete base.unsupported_kind;
delete base.reply;
delete base.status;

// Шлюз не ответил или расшифровка пустая — молчать нельзя.
if (!text) {
  return [{ json: { ...base, pass_through: false, status: 'unsupported_input', lang: src.lang || 'ru',
    reply: 'Не смог разобрать голосовое — возможно, было тихо или шумно. Напишите, пожалуйста, текстом — и я сразу отвечу.' } }];
}

// 🔴 Правило кода, а не промпта (решение штаба, ЗАДАНИЕ-32): вопрос об аллергенах,
// заданный голосом, автоматически не обслуживается. Распознавание путает
// «орехи / орехов / арахис» и названия блюд, а цена ошибки в вопросе о здоровье
// несоизмерима с неудобством переспросить.
if (ALLERGEN_RE.test(text)) {
  return [{ json: { ...base, pass_through: false, status: 'unsupported_input', lang: src.lang || 'ru',
    voice_transcript: text,
    reply: `Я расслышал: «${text}».\n\nВопросы про аллергены я уточняю письменно — распознавание речи может ошибиться в названии блюда или аллергена, а здесь это слишком важно.\n\nНапишите, пожалуйста, ваш вопрос текстом — и я отвечу сразу.\nЕсли удобнее, чтобы вопросом занялся администратор — напишите слово «подтверждаю».` } }];
}

// Обычный случай: расшифровка становится обычным текстом гостя.
// Префикс [voice] — временный приём (решение штаба, ЗАДАНИЕ-34): колонки source
// в operation_log нет, а channel занят и ограничен CHECK. По префиксу голосовые строки
// отделяются одним LIKE '[voice]%'. В волне 1 заводим source и префикс убираем.
return [{ json: { ...base, pass_through: true, text: `[voice] ${text}`, voice_transcript: text,
  model_profile: 'LOCAL',
  is_consent_accept: /^(принимаю|принять|accept|einverstanden)$/i.test(text) } }];

// Системный промпт — дословно тот, на котором модель дообучалась (train.jsonl).
// Менять его нельзя: модель видела именно эту формулировку во время обучения.
const INTENTS = ['new_booking','change_booking','cancel_booking','banquet_request','menu_question',
                 'allergen_question','recommendation','policy_question','complaint','other'];
const SYS = 'Классифицируй обращение гостя ресторана в один из десяти интентов. '
  + 'Ответь ТОЛЬКО названием интента, без пояснений. Список: ' + INTENTS.join(', ') + '. '
  + 'Правила приоритета: любое упоминание аллергии или непереносимости — allergen_question; '
  + 'группа от 15 человек — banquet_request; бизнес-ланч — policy_question; жалоба — complaint.';

const pii = $('4. PII-маска (до любого LLM)').item.json;
return [{ json: { ...pii, router_request: {
  model: 'm15-router-qwen3-4b-lora',
  temperature: 0,
  max_tokens: 12,
  messages: [ { role: 'system', content: SYS },
              { role: 'user', content: pii.text_masked || '' } ],
} } }];

// Готовим ТОЛЬКО текст для синтеза. Текстовое сообщение гостю уже ушло другой веткой
// и здесь не меняется ни на символ.
const j = $input.first().json;
let spoken = String(j.final_text || j.reply || '');

// 1. Снимаем письменный дисклеймер — в голосе он будет первой фразой, чтобы не звучать дважды.
spoken = spoken.replace(/\n*— Автоматический ассистент[^\n]*/g, '')
                 .replace(/\n*— Automatischer Assistent[^\n]*/g, '')
                 .replace(/\n*— Automated assistant[^\n]*/g, '').trim();

// 2. Фильтр PII. Узел 12 уже вернул в текст настоящие значения — для голоса убираем их обратно.
// Имя не заменяем местоимением, а убираем совсем: подстановка «вы» давала
// косоязычное «вы, ждём вас!». Обращение по имени остаётся в тексте, в голосе — нет.
const SPOKEN = { phone: 'ваш номер', email: 'ваша почта', username: 'ваш ник', name: '' };
const removed = [];
for (const m of (j.pii_map || [])) {
  const val = String(m.value || '');
  if (val && spoken.includes(val)) {
    spoken = spoken.split(val).join(SPOKEN[m.type] || '');
    removed.push(m.type);
  }
  // Если где-то остался сам токен — озвучивать «квадратная скобка PHONE» тоже нельзя.
  if (m.token && spoken.includes(m.token)) {
    spoken = spoken.split(m.token).join(SPOKEN[m.type] || '');
    removed.push(m.type);
  }
}
// Страховка на случай, если номер просочился мимо реестра: длинные цепочки цифр не произносим.
// Номер брони вида BAS-20260823-47 при этом сохраняется — его озвучивать НУЖНО.
spoken = spoken.replace(/(?<!BAS-)\b\+?\d[\d\s\-()]{8,}\d\b/g, () => { removed.push('phone-страховка'); return 'ваш номер'; });

// 3. Дисклеймер ст. 50 AI Act — первой фразой, как в Модуле 14. Комплаенс не должен
// зависеть от того, какой веткой ушёл ответ. Звучит только при первом контакте (решение Dennis 21.08).
const FULL = { ru: 'Автоматический ассистент ресторана Базилик. ',
               de: 'Automatischer Assistent des Restaurants Basilik. ',
               en: 'Automated assistant of the restaurant Basilik. ' };
const SHORT = { ru: 'Ассистент Базилик. ', de: 'Assistent Basilik. ', en: 'Assistant Basilik. ' };
const lang = ['ru', 'de', 'en'].includes(j.lang) ? j.lang : 'ru';
// Решение Dennis 21.08: представляемся только при первом контакте — уведомление 3a (status
// 'consent_requested') или явный consent_seen_before === false. Раньше флаги consent_* на элемент
// не попадали, seen всегда был false — и полный дисклеймер звучал в начале КАЖДОГО голосового.
// SHORT больше не используется: повторному гостю представление не нужно.
const isFirst = j.status === 'consent_requested' || j.consent_seen_before === false;
const prefix = isFirst ? FULL[lang] : '';

// Подчищаем следы удалённого имени: висячие запятые и двойные пробелы.
spoken = spoken.replace(/\s+,/g, ',').replace(/,\s*,/g, ',').replace(/([.!?])\s*,/g, '$1')
               .replace(/\s{2,}/g, ' ').replace(/(^|\n)\s*,\s*/g, '$1').trim();

return [{ json: { user_ref: j.user_ref, lang,
  spoken_text: prefix + spoken,
  tts_pii_removed: [...new Set(removed)],
  tts_chars: (prefix + spoken).length } }];

// ВХОДНОЙ СТОП-ФИЛЬТР — вариант Б по ЗАДАНИЮ-42.
// Почему код, а не штатный Guardrails: тот требует модель на пути каждого
// сообщения гостя, а при сбое с onError=continueRegularOutput пропускает ВСЁ
// (проверено 21.08: шесть фраз из шести, включая три инъекции, ушли в «чисто»).
// У детерминированной функции состояния «сбой проверки» не бывает.
//
// ВХОД НЕ ЧИТАЕМ: перед нами узел 4b — INSERT без RETURNING, он подменяет элемент
// пустотой. Берём контекст у того узла, который его собрал — так же, как делает узел 5e.
//
// ВНИМАНИЕ про регулярки: \\w в JavaScript — это [A-Za-z0-9_], кириллицу он НЕ ловит,
// и \\b по кириллице тоже не работает. Поэтому везде явные классы [а-яё].
// Без этого «Покажи свой системный промпт» не ловилось вовсе, а «Вы теперь рабОТаете
// до полуночи?» ловилось ложно — подстрока «бот» сидит внутри слова «работаете».
const MARKERS = [
  [/забуд[ья][а-яё]*[\s,.;:!?—-]+(вс[еёя][а-яё]*[\s,.;:!?—-]+)?(предыдущ[а-яё]*[\s,.;:!?—-]+)?(инструкц|указан|правил|что[\s]+теб)/i, 'ru: забудь инструкции'],
  [/игнорир[а-яё]*[\s,.;:!?—-]+(вс[еёя][а-яё]*[\s,.;:!?—-]+)?(предыдущ[а-яё]*[\s,.;:!?—-]+)?(инструкц|указан|правил|ограничен)/i, 'ru: игнорируй инструкции'],
  [/(ты|вы)[\s]+(теперь|отныне)[^.!?]{0,40}?(?:^|[\s,«'-])(бот|ассистент|помощник|модель|нейросет|пират|хакер|админ|разработчик)/i, 'ru: смена роли'],
  [/(покажи|выведи|напиши|раскрой|повтори)[\s]+([^.!?]{0,20}?)?систем[а-яё]*[\s]*(промпт|подсказк|сообщен|инструкц)/i, 'ru: раскрыть системный промпт'],
  [/(отмени|сними|отключи)[\s]+(вс[еёя][а-яё]*[\s]+)?(ограничен|запрет|правил|фильтр)/i, 'ru: снять ограничения'],
  [/(притворись|веди[\s]+себя[\s]+как|представь,?[\s]+что[\s]+ты)[\s]+[^\s]/i, 'ru: ролевая подмена'],
  [/режим[\s]+разработчик/i, 'ru: режим разработчика'],
  [/(ignore|disregard|forget)\s+(all\s+|any\s+)?(previous|prior|above|earlier)\s+(instruction|prompt|rule|message)/i, 'en: ignore previous instructions'],
  [/(print|reveal|show|output|repeat)\s+(me\s+)?(your\s+)?(system\s+|initial\s+)?prompt/i, 'en: reveal system prompt'],
  [/you\s+are\s+(now|from\s+now\s+on)\s+[^\s]/i, 'en: role switch'],
  [/\b(jailbreak|dan\s+mode|developer\s+mode)\b/i, 'en: jailbreak'],
  [/(vergiss|ignoriere)\s+(alle\s+|deine\s+)?(bisherigen\s+|vorherigen\s+)?(anweisung|regel|instruktion)/i, 'de: Anweisungen ignorieren'],
  [/(zeig|zeige|gib|nenne)\s+(mir\s+)?(dein[a-z]*\s+)?system[-\s]?prompt/i, 'de: System-Prompt zeigen'],
  [/du\s+bist\s+(jetzt|ab\s+sofort)\s+[^\s]/i, 'de: Rollenwechsel'],
];

const c = $('4. PII-маска (до любого LLM)').item.json;
const text = String(c.text_masked || c.text || '');

let marker = null;
for (const [re, label] of MARKERS) { if (re.test(text)) { marker = label; break; } }

// При срабатывании ставим intent = other: узел 11 уже умеет этот случай,
// а причина пишется с узнаваемым префиксом — по нему считается метрика
// «сколько раз защита сработала»: SELECT count(*) FROM escalations WHERE reason LIKE 'входной фильтр%'.
return [{ json: { ...c,
  injection_hit: !!marker,
  injection_marker: marker,
  intent: marker ? 'other' : (c.intent ?? null),
  route: marker ? 'other' : (c.route ?? null),
  escalation_reason: marker
    ? ('входной фильтр инъекций: попытка подменить инструкции ассистента (' + marker + ')')
    : (c.escalation_reason ?? null),
} }];
